model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Cart "/" {
  state products: Product[] = [
    { id: "1", name: "Remera", price: 15.5 },
    { id: "2", name: "Zapatillas", price: 89.99 },
    { id: "3", name: "Gorra", price: 12 }
  ]
  state cart: CartItem[] = []

  computed total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)

  fn add(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      cart = cart.map(i => i.id == p.id ? { id: i.id, name: i.name, price: i.price, qty: i.qty + 1 } : i)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn change(id, delta) {
    cart = cart
      .map(i => i.id == id ? { id: i.id, name: i.name, price: i.price, qty: i.qty + delta } : i)
      .filter(i => i.qty > 0)
  }

  column gap=6 pad=6 {
    title "Tienda" large
    column gap=2 {
      for p in products {
        card pad=3 {
          row gap=4 align=center justify=between {
            column gap=1 {
              text p.name bold
              text `$${p.price.toFixed(2)}` muted
            }
            button "Agregar" primary -> add(p)
          }
        }
      }
    }
    title "Carrito"
    if cart.length == 0 {
      text "El carrito está vacío" muted
    } else {
      column gap=2 {
        for i in cart {
          card pad=3 {
            row gap=4 align=center justify=between {
              column gap=1 {
                text i.name bold
                text `$${i.price.toFixed(2)} c/u` muted small
              }
              row gap=2 align=center {
                button "-" small -> change(i.id, -1)
                text `${i.qty}`
                button "+" small -> change(i.id, 1)
              }
            }
          }
        }
      }
    }
    text `Total: $${total.toFixed(2)}` bold large
  }
}
